"use client";

import { useEffect, useState } from "react";
export function ReadingProgress({
  color
}: {
  color?: string;
}) {
  const [progress, setProgress] = useState(0);
  useEffect(() => {
    function handleScroll() {
      const scrollTop = window.scrollY;
      const docHeight = document.documentElement.scrollHeight - window.innerHeight;
      if (docHeight > 0) {
        setProgress(Math.min(scrollTop / docHeight * 100, 100));
      }
    }
    window.addEventListener("scroll", handleScroll, {
      passive: true
    });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);
  return <div className="fixed top-0 left-0 right-0 z-[100] h-[3px] bg-transparent" role="progressbar" aria-valuenow={Math.round(progress)} aria-valuemin={0} aria-valuemax={100} aria-label="Reading progress" data-sentry-component="ReadingProgress" data-sentry-source-file="ReadingProgress.tsx">
      <div className="h-full transition-[width] duration-150 ease-out" style={{
      width: `${progress}%`,
      backgroundColor: color ?? "#733DD9"
    }} />
    </div>;
}